        /** Time since system boot, millisecond resolution. MAVLink carries it as a uint32, which wraps after about 49.7 days. */
        class MillisecondsSinceBoot : Duration {
            public long     max       => uint.MaxValue;
            public TimeSpan precision => TimeSpan.FromMilliseconds(1);
        }

        /** Time since system boot, microsecond resolution. */
        class MicrosecondsSinceBoot : Duration {
            public long     max       => uint.MaxValue;
            public TimeSpan precision => TimeSpan.FromMicroseconds(1);
        }


