        /**
        The heartbeat message shows that a system or component is present and responding. The type and autopilot
        fields (along with the message component id), allow the receiving system to treat further messages from this
        system appropriately (e.g. by laying out the user interface based on the autopilot). This microservice is
        documented at https://mavlink.io/en/services/heartbeat.html
        */
        class HEARTBEAT {
            public const int mavlink_message_id = 0;
            /**
            Vehicle or component type. For a flight controller component the vehicle type (quadrotor, helicopter, etc.).
            For other components the component type (e.g. camera, gimbal, etc.). This should be used in preference to
            component id for identifying the component type.
            */
            MAV_TYPE Type;
            /**
            Autopilot type / class. Use MAV_AUTOPILOT_INVALID for components that are not flight controllers.
            */
            MAV_AUTOPILOT autopilot;
            /**
            System mode bitmap.
            */
            MAV_MODE_FLAG base_mode;
            /**
            A bitfield for use for autopilot-specific flags
            */
            uint custom_mode;
            /**
            System status flag.
            */
            MAV_STATE system_status;
            /**
            MAVLink version, not writable by user, gets added by protocol because of magic data type:
            uint8_t_mavlink_version
            */
            byte mavlink_version;
        }

        // ═════════════════════════ messages of standard.xml ═════════════════════════

        /**
        The filtered global position (e.g. fused GPS and accelerometers). The position is in GPS-frame (right-handed,
        Z-up). It is designed as scaled integer message since the resolution of float is not sufficient.
        */
        class GLOBAL_POSITION_INT {
            public const int mavlink_message_id = 33;
            /**
            Timestamp (time since system boot).
            */
            [Units(SI_Unit.time.ms)] MillisecondsSinceBoot time_boot_ms;
            /**
            Latitude, expressed
            */
            [Units(SI_Unit.angle.degE7)] int lat;
            /**
            Longitude, expressed
            */
            [Units(SI_Unit.angle.degE7)] int lon;
            /**
            Altitude (MSL). Note that virtually all GPS modules provide both WGS84 and MSL.
            */
            [Units(SI_Unit.distance.mm)] int alt;
            /**
            Altitude above home
            */
            [Units(SI_Unit.distance.mm)] int relative_alt;
            /**
            Ground X Speed (Latitude, positive north)
            */
            [Units(SI_Unit.distance.cm_s)] short vx;
            /**
            Ground Y Speed (Longitude, positive east)
            */
            [Units(SI_Unit.distance.cm_s)] short vy;
            /**
            Ground Z Speed (Altitude, positive down)
            */
            [Units(SI_Unit.distance.cm_s)] short vz;
            /**
            Vehicle heading (yaw angle), 0.0..359.99 degrees. If unknown, set to: UINT16_MAX
            */
            [Units(SI_Unit.angle.cdeg), Invalid("UINT16_MAX")] ushort hdg;
        }

        /**
        Version and capability of autopilot software. This should be emitted in response to a request with
        MAV_CMD_REQUEST_MESSAGE.
        */
        class AUTOPILOT_VERSION {
            public const int mavlink_message_id = 148;
            /**
            Bitmap of capabilities
            */
            MAV_PROTOCOL_CAPABILITY capabilities;
            /**
            Firmware version number.
            The field must be encoded as 4 bytes, where each byte (shown from MSB to LSB) is part of a semantic version:
            (major) (minor) (patch) (FIRMWARE_VERSION_TYPE).
            */
            uint flight_sw_version;
            /**
            Middleware version number
            */
            uint middleware_sw_version;
            /**
            Operating system version number
            */
            uint os_sw_version;
            /**
            HW / board version (last 8 bits should be silicon ID, if any). The first 16 bits of this field specify a board
            type from an enumeration stored at https://github.com/PX4/PX4-Bootloader/blob/master/board_types.txt and with
            extensive additions at https://github.com/ArduPilot/ardupilot/blob/master/Tools/AP_Bootloader/board_types.txt
            */
            uint board_version;
            /**
            Custom version field, commonly the first 8 bytes of the git hash. This is not an unique identifier, but should
            allow to identify the commit using the main version number even for very large code bases.
            */
            [D(8)] byte[] flight_custom_version;
            /**
            Custom version field, commonly the first 8 bytes of the git hash. This is not an unique identifier, but should
            allow to identify the commit using the main version number even for very large code bases.
            */
            [D(8)] byte[] middleware_custom_version;
            /**
            Custom version field, commonly the first 8 bytes of the git hash. This is not an unique identifier, but should
            allow to identify the commit using the main version number even for very large code bases.
            */
            [D(8)] byte[] os_custom_version;
            /**
            ID of the board vendor
            */
            ushort vendor_id;
            /**
            ID of the product
            */
            ushort product_id;
            /**
            UID if provided by hardware (see uid2)
            */
            ulong uid;
            /**
            UID if provided by hardware (supersedes the uid field. If this is non-zero, use this field, otherwise use uid)
            */
            [D(18), ExtensionField] byte[] uid2;
        }

        // ═════════════════════════ messages of common.xml ═════════════════════════

        /**
        Sensor and subsystem status information. Provides a compact representation of sensor/subsystem status and a
        few other basic statistics.
        */
        class SYS_STATUS {
            public const int mavlink_message_id = 1;
            /**
            Bitmap showing which onboard controllers and sensors are present. Value of 0: not present. Value of 1:
            present.
            */
            [PrintFormat("0x%04x")] MAV_SYS_STATUS_SENSOR onboard_control_sensors_present;
            /**
            Bitmap showing which onboard controllers and sensors are enabled:  Value of 0: not enabled. Value of 1:
            enabled.
            */
            [PrintFormat("0x%04x")] MAV_SYS_STATUS_SENSOR onboard_control_sensors_enabled;
            /**
            Bitmap showing which onboard controllers and sensors have an error (or are operational). Value of 0: error.
            Value of 1: healthy.
            */
            [PrintFormat("0x%04x")] MAV_SYS_STATUS_SENSOR onboard_control_sensors_health;
            /**
            Maximum usage in percent of the mainloop time. Values: [0-1000] - should always be below 1000
            */
            [Units(SI_Unit.ratio.decipercent)] ushort load;
            /**
            Battery voltage, UINT16_MAX: Voltage not sent by autopilot. Value is ambiguous on multi-battery systems.
            BATTERY_STATUS is a recommended alternative.
            */
            [Units(SI_Unit.electricity.mV), Invalid("UINT16_MAX")] ushort voltage_battery;
            /**
            Battery current, -1: Current not sent by autopilot. Value may overflow/rollover for very high currents (&gt;
            327.67A). Value is ambiguous on multi-battery systems. BATTERY_STATUS is a recommended alternative.
            */
            [Units(SI_Unit.electricity.cA), Invalid("-1")] short current_battery;
            /**
            Battery energy remaining, -1: Battery remaining energy not sent by autopilot. Value is ambiguous on
            multi-battery systems. BATTERY_STATUS is a recommended alternative.
            */
            [Units(SI_Unit.ratio.percent), Invalid("-1")] sbyte battery_remaining;
            /**
            Communication drop rate, (UART, I2C, SPI, CAN), dropped packets on all links (packets that were corrupted on
            reception on the MAV)
            */
            [Units(SI_Unit.ratio.centipercent)] ushort drop_rate_comm;
            /**
            Communication errors (UART, I2C, SPI, CAN), dropped packets on all links (packets that were corrupted on
            reception on the MAV)
            */
            ushort errors_comm;
            /**
            Autopilot-specific errors
            */
            ushort errors_count1;
            /**
            Autopilot-specific errors
            */
            ushort errors_count2;
            /**
            Autopilot-specific errors
            */
            ushort errors_count3;
            /**
            Autopilot-specific errors
            */
            ushort errors_count4;
            /**
            Bitmap showing which onboard controllers and sensors are present. Value of 0: not present. Value of 1:
            present.
            */
            [PrintFormat("0x%04x"), ExtensionField] MAV_SYS_STATUS_SENSOR_EXTENDED onboard_control_sensors_present_extended;
            /**
            Bitmap showing which onboard controllers and sensors are enabled:  Value of 0: not enabled. Value of 1:
            enabled.
            */
            [PrintFormat("0x%04x"), ExtensionField] MAV_SYS_STATUS_SENSOR_EXTENDED onboard_control_sensors_enabled_extended;
            /**
            Bitmap showing which onboard controllers and sensors have an error (or are operational). Value of 0: error.
            Value of 1: healthy.
            */
            [PrintFormat("0x%04x"), ExtensionField] MAV_SYS_STATUS_SENSOR_EXTENDED onboard_control_sensors_health_extended;
        }

        /**
        The system time is the time of the sender's master clock.
        This can be emitted by flight controllers, onboard computers, or other components in the MAVLink network.
        Components that are using a less reliable time source, such as a battery-backed real time clock, can choose to
        match their system clock to that of a system that indicates a more recent time.
        This allows more broadly accurate date stamping of logs, and so on.
        If precise time synchronization is needed then use TIMESYNC instead.
        */
        class SYSTEM_TIME {
            public const int mavlink_message_id = 2;
            /**
            Timestamp (UNIX epoch time).
            */
            [Units(SI_Unit.time.us)] ulong time_unix_usec;
            /**
            Timestamp (time since system boot).
            */
            [Units(SI_Unit.time.ms)] MillisecondsSinceBoot time_boot_ms;
        }

        /**
        A ping message either requesting or responding to a ping. This allows to measure the system latencies,
        including serial port, radio modem and UDP connections. The ping microservice is documented at
        https://mavlink.io/en/services/ping.html
        ⚠ SUPERSEDED since 2011-08, replaced by TIMESYNC: To be removed / merged with TIMESYNC
        */
        class PING {
            public const int mavlink_message_id = 4;
            /**
            Timestamp (UNIX Epoch time or time since system boot). The receiving end can infer timestamp format (since
            1.1.1970 or since system boot) by checking for the magnitude of the number.
            */
            [Units(SI_Unit.time.us)] ulong time_usec;
            /**
            PING sequence
            */
            uint seq;
            /**
            0: request ping from all receiving systems. If greater than 0: message is a ping response and number is the
            system id of the requesting system
            */
            byte target_system;
            /**
            0: request ping from all receiving components. If greater than 0: message is a ping response and number is the
            component id of the requesting component.
            */
            byte target_component;
        }

        /**
        Request to control this MAV
        */
        class CHANGE_OPERATOR_CONTROL {
            public const int mavlink_message_id = 5;
            /**
            System the GCS requests control for
            */
            byte target_system;
            /**
            0: request control of this MAV, 1: Release control of this MAV
            */
            byte control_request;
            /**
            0: key as plaintext, 1-255: future, different hashing/encryption variants. The GCS should in general use the
            safest mode possible initially and then gradually move down the encryption level if it gets a NACK message
            indicating an encryption mismatch.
            */
            byte version;
            /**
            Password / Key, depending on version plaintext or encrypted. 25 or less characters, NULL terminated. The
            characters may involve A-Z, a-z, 0-9, and "!?,.-"
            */
            [D(+25)] string passkey;
        }

        /**
        Accept / deny control of this MAV
        */
        class CHANGE_OPERATOR_CONTROL_ACK {
            public const int mavlink_message_id = 6;
            /**
            ID of the GCS this message
            */
            byte gcs_system_id;
            /**
            0: request control of this MAV, 1: Release control of this MAV
            */
            byte control_request;
            /**
            0: ACK, 1: NACK: Wrong passkey, 2: NACK: Unsupported passkey encryption method, 3: NACK: Already under control
            */
            byte ack;
        }

        /**
        Emit an encrypted signature / key identifying this system. PLEASE NOTE: This protocol has been kept simple, so
        transmitting the key requires an encrypted channel for true safety.
        */
        class AUTH_KEY {
            public const int mavlink_message_id = 7;
            /**
            key
            */
