            /**
            Aux continuous input field 2. Normalized in the range [-1000,1000]. Purpose defined by recipient. Valid data
            if bit 3 of enabled_extensions field is set. 0 if bit 3 is unset.
            */
            [MinValue(-1000), MaxValue(1000), ExtensionField] short aux2;
            /**
            Aux continuous input field 3. Normalized in the range [-1000,1000]. Purpose defined by recipient. Valid data
            if bit 4 of enabled_extensions field is set. 0 if bit 4 is unset.
            */
            [MinValue(-1000), MaxValue(1000), ExtensionField] short aux3;
            /**
            Aux continuous input field 4. Normalized in the range [-1000,1000]. Purpose defined by recipient. Valid data
            if bit 5 of enabled_extensions field is set. 0 if bit 5 is unset.
            */
            [MinValue(-1000), MaxValue(1000), ExtensionField] short aux4;
            /**
            Aux continuous input field 5. Normalized in the range [-1000,1000]. Purpose defined by recipient. Valid data
            if bit 6 of enabled_extensions field is set. 0 if bit 6 is unset.
            */
            [MinValue(-1000), MaxValue(1000), ExtensionField] short aux5;
            /**
            Aux continuous input field 6. Normalized in the range [-1000,1000]. Purpose defined by recipient. Valid data
            if bit 7 of enabled_extensions field is set. 0 if bit 7 is unset.
            */
            [MinValue(-1000), MaxValue(1000), ExtensionField] short aux6;
