        /**
        Battery information. Updates GCS with flight controller battery status. Smart batteries also use this message,
        but may additionally send BATTERY_INFO.
        */
        class BATTERY_STATUS {
            public const int mavlink_message_id = 147;
            /**
            Battery ID
            */
            [Instance] byte id;
            /**
            Function of the battery
            */
            MAV_BATTERY_FUNCTION battery_function;
            /**
            Type (chemistry) of the battery
            */
            MAV_BATTERY_TYPE Type;
            /**
            Temperature of the battery. INT16_MAX for unknown temperature.
            */
            [Units(SI_Unit.temperature.cdegC), Invalid("INT16_MAX")] short temperature;
            /**
            Battery voltage of cells 1 to 10 (see voltages_ext for cells 11-14). Cells in this field above the valid cell
            count for this battery should have the UINT16_MAX value. If individual cell voltages are unknown or not
            measured for this battery, then the overall battery voltage should be filled in cell 0, with all others set to
            UINT16_MAX. If the voltage of the battery is greater than (UINT16_MAX - 1), then cell 0 should be set to
            (UINT16_MAX - 1), and cell 1 to the remaining voltage. This can be extended to multiple cells if the total
            voltage is greater than 2 * (UINT16_MAX - 1).
            */
            [D(10), Units(SI_Unit.electricity.mV), Invalid("[UINT16_MAX]")] ushort[] voltages;
            /**
            Battery current, -1: autopilot does not measure the current. Value may overflow/rollover for very high
            currents (&gt; 327.67A)
            */
            [Units(SI_Unit.electricity.cA), Invalid("-1")] short current_battery;
            /**
            Consumed charge, -1: autopilot does not provide consumption estimate
            */
            [Units(SI_Unit.electricity.mAh), Invalid("-1")] int current_consumed;
            /**
            Consumed energy, -1: autopilot does not provide energy consumption estimate
            */
            [Units(SI_Unit.energy.hJ), Invalid("-1")] int energy_consumed;
            /**
            Remaining battery energy. Values: [0-100], -1: autopilot does not estimate the remaining battery.
            */
            [Units(SI_Unit.ratio.percent), Invalid("-1")] sbyte battery_remaining;
            /**
            Remaining battery time, 0: autopilot does not provide remaining battery time estimate
            */
            [Units(SI_Unit.time.s), Invalid("0"), ExtensionField] int time_remaining;
            /**
            State for extent of discharge, provided by autopilot for warning or external reactions
            */
            [ExtensionField] MAV_BATTERY_CHARGE_STATE charge_state;
            /**
            Battery voltages for cells 11 to 14. Cells above the valid cell count for this battery should have a value of
            0, where zero indicates not supported (note, this is different than for the voltages field and allows empty
            byte truncation). If the measured value is 0 then 1 should be sent instead.
            */
            [D(4), Units(SI_Unit.electricity.mV), Invalid("[0]"), ExtensionField] ushort[] voltages_ext;
            /**
            Battery mode. Default (0) is that battery mode reporting is not supported or battery is in normal-use mode.
            */
            [ExtensionField] MAV_BATTERY_MODE mode;
            /**
            Fault/health indications. These should be set when charge_state is MAV_BATTERY_CHARGE_STATE_FAILED or
            MAV_BATTERY_CHARGE_STATE_UNHEALTHY (if not, fault reporting is not supported).
            */
            [ExtensionField] MAV_BATTERY_FAULT fault_bitmask;
        }

