        /**
        Obstacle distances in front of the sensor, starting from the left in increment degrees to the right
        */
        class OBSTACLE_DISTANCE {
            public const int mavlink_message_id = 330;
            /**
            Timestamp (UNIX Epoch time or time since system boot). The receiving end can infer timestamp format (since
            1.1.1970 or since system boot) by checking for the magnitude of the number.
            */
            [Units(SI_Unit.time.us)] ulong time_usec;
            /**
            Class id of the distance sensor type.
            */
            MAV_DISTANCE_SENSOR sensor_type;
            /**
            Distance of obstacles around the vehicle with index 0 corresponding to north + angle_offset, unless otherwise
            specified in the frame. A value of 0 is valid and means that the obstacle is practically touching the sensor.
            A value of max_distance +1 means no obstacle is present. A value of UINT16_MAX for unknown/not used. In a
            array element, one unit corresponds to 1cm.
            */
            [D(72), Units(SI_Unit.distance.cm), Invalid("[UINT16_MAX]")] ushort[] distances;
            /**
            Angular width in degrees of each array element. Increment direction is clockwise. This field is ignored if
            increment_f is non-zero.
            */
            [Units(SI_Unit.angle.deg)] byte increment;
            /**
            Minimum distance the sensor can measure.
            */
            [Units(SI_Unit.distance.cm)] ushort min_distance;
            /**
            Maximum distance the sensor can measure.
            */
            [Units(SI_Unit.distance.cm)] ushort max_distance;
            /**
            Angular width in degrees of each array element as a float. If non-zero then this value is used instead of the
            uint8_t increment field. Positive is clockwise direction, negative is counter-clockwise.
            */
            [Units(SI_Unit.angle.deg), ExtensionField] float increment_f;
            /**
            Relative angle offset of the 0-index element in the distances array. Value of 0 corresponds to forward.
            Positive is clockwise direction, negative is counter-clockwise.
            */
            [Units(SI_Unit.angle.deg), ExtensionField] float angle_offset;
            /**
            Coordinate frame of reference for the yaw rotation and offset of the sensor data. Defaults to
            MAV_FRAME_GLOBAL, which is north aligned. For body-mounted sensors use MAV_FRAME_BODY_FRD, which is vehicle
            front aligned.
            */
            [ExtensionField] MAV_FRAME frame;
        }

        /**
        Odometry message to communicate odometry information with an external interface. Fits ROS REP 147 standard for
        aerial vehicles (http://www.ros.org/reps/rep-0147.html).
        */
        class ODOMETRY {
            public const int mavlink_message_id = 331;
            /**
            Timestamp (UNIX Epoch time or time since system boot). The receiving end can infer timestamp format (since
            1.1.1970 or since system boot) by checking for the magnitude of the number.
            */
            [Units(SI_Unit.time.us)] ulong time_usec;
            /**
            Coordinate frame of reference for the pose data.
            */
            MAV_FRAME frame_id;
            /**
            Coordinate frame of reference for the velocity in free space (twist) data.
            */
            MAV_FRAME child_frame_id;
            /**
            X Position
            */
            [Units(SI_Unit.distance.m)] float x;
            /**
            Y Position
            */
            [Units(SI_Unit.distance.m)] float y;
            /**
            Z Position
            */
            [Units(SI_Unit.distance.m)] float z;
            /**
            Quaternion components, w, x, y, z (1 0 0 0 is the null-rotation)
            */
            [D(4)] float[] q;
            /**
            X linear speed
            */
            [Units(SI_Unit.distance.m_s)] float vx;
            /**
            Y linear speed
            */
            [Units(SI_Unit.distance.m_s)] float vy;
            /**
            Z linear speed
            */
            [Units(SI_Unit.distance.m_s)] float vz;
            /**
            Roll angular speed
            */
            [Units(SI_Unit.angle.rad_s)] float rollspeed;
            /**
            Pitch angular speed
            */
            [Units(SI_Unit.angle.rad_s)] float pitchspeed;
            /**
            Yaw angular speed
            */
            [Units(SI_Unit.angle.rad_s)] float yawspeed;
            /**
            Row-major representation of a 6x6 pose cross-covariance matrix upper right triangle (states: x, y, z, roll,
            pitch, yaw; first six entries are the first ROW, next five entries are the second ROW, etc.). If unknown,
            assign NaN value to first element in the array.
            */
            [D(21), Invalid("[NaN:]")] float[] pose_covariance;
            /**
            Row-major representation of a 6x6 velocity cross-covariance matrix upper right triangle (states: vx, vy, vz,
            rollspeed, pitchspeed, yawspeed; first six entries are the first ROW, next five entries are the second ROW,
            etc.). If unknown, assign NaN value to first element in the array.
            */
            [D(21), Invalid("[NaN:]")] float[] velocity_covariance;
            /**
            Estimate reset counter. This should be incremented when the estimate resets in any of the dimensions
            (position, velocity, attitude, angular speed). This is designed to be used when e.g an external SLAM system
            detects a loop-closure and the estimate jumps.
            */
            [ExtensionField] byte reset_counter;
            /**
            Type of estimator that is providing the odometry.
            */
            [ExtensionField] MAV_ESTIMATOR_TYPE estimator_type;
            /**
            Optional odometry quality metric as a percentage. -1 = odometry has failed, 0 = unknown/unset quality, 1 =
            worst quality, 100 = best quality
            */
            [Units(SI_Unit.ratio.percent), Invalid("0"), ExtensionField] sbyte quality;
        }

