        /**
        Cellular network status as reported by a particular modem.
        This is primarily intended for logging, but a GCS may choose to display link_tx_rate and link_rx_rate.
        Note that a value of 0 in the id field indicates that the sender does not support reporting of multiple
        modems.
        Message data should be from a single modem, but that is not guaranteed.
        */
        class CELLULAR_STATUS {
            public const int mavlink_message_id = 334;
            /**
            Cellular modem status
            */
            CELLULAR_STATUS_FLAG status;
            /**
            Failure reason when status in in CELLULAR_STATUS_FLAG_FAILED
            */
            CELLULAR_NETWORK_FAILED_REASON failure_reason;
            /**
            Cellular network radio type: gsm, cdma, lte...
            */
            CELLULAR_NETWORK_RADIO_TYPE Type;
            /**
            Signal quality in percent. If unknown, set to UINT8_MAX
            */
            [Invalid("UINT8_MAX")] byte quality;
            /**
            Mobile country code. If unknown, set to UINT16_MAX
            */
            [Invalid("UINT16_MAX")] ushort mcc;
            /**
            Mobile network code. If unknown, set to UINT16_MAX
            */
            [Invalid("UINT16_MAX")] ushort mnc;
            /**
            Location area code. If unknown, set to 0
            */
            [Invalid("0")] ushort lac;
            /**
            Cellular modem instance number. Indexed from 1.
            */
            [Instance, MinValue(1), ExtensionField] byte id;
            /**
            Download rate.
            */
            [Units(SI_Unit.digital.KiB_s), Invalid("0"), ExtensionField] uint link_tx_rate;
            /**
            Upload rate.
            */
            [Units(SI_Unit.digital.KiB_s), Invalid("0"), ExtensionField] uint link_rx_rate;
            /**
            ID of the currently connected cell tower. This must be NULL terminated if the length is less than 9
            human-readable chars, and without the null termination (NULL) byte if the length is exactly 9 chars.
            */
            [D(+9), Invalid("0"), ExtensionField] string cell_tower_id;
            /**
            LTE frequency band number.
            */
            [Invalid("0"), ExtensionField] byte band_number;
            /**
            LTE radio frequency.
            */
            [Units(SI_Unit.time.MHz), Invalid("0"), ExtensionField] float band_frequency;
            /**
            The channel number (CN). Absolute radio-frequency (ARFCN) / E-UTRA (EARFCN) / UTRA (UARFCN) / New radio
            (NR_CH).
            */
            [Invalid("0"), ExtensionField] uint channel_number;
            /**
            On 3G is Received Signal Code Power (RSCP). On LTE is Reference Signal Received Power (RSRP). On 5G is New
            Radio Reference Signal Received Power (NR_RSRP).
            */
            [Units(SI_Unit.ratio.dBm), Invalid("0"), ExtensionField] float rx_level;
            /**
            Transmitter (modem) signal absolute power level.
            */
            [Units(SI_Unit.ratio.dBm), Invalid("0"), ExtensionField] float tx_level;
            /**
            On 3G is Receiver Quality (RxQual). On LTE is Reference Signal Received Quality (RSRQ). On 5G is New Radio
            Reference Signal Received Quality (NR_RSRQ).
            */
            [Units(SI_Unit.ratio.dBm), Invalid("0"), ExtensionField] float rx_quality;
            /**
            Signal to interference plus noise ratio (SINR).
            */
            [Units(SI_Unit.ratio.dB), Invalid("0"), ExtensionField] float sinr;
        }

