            /**
            The current mode index within number_modes, indexed from 1. The index is not guaranteed to be persistent, and
            may change between reboots or if the set of modes change.
            */
            byte mode_index;
            /**
            Standard mode.
            */
            MAV_STANDARD_MODE standard_mode;
            /**
            A bitfield for use for autopilot-specific flags
            */
            uint custom_mode;
            /**
            Mode properties.
            */
            MAV_MODE_PROPERTY properties;
            /**
            Name of custom mode, with null termination character. Should be omitted for standard modes.
            */
            [D(+35)] string mode_name;
            /**
            Sequence number. The value iterates sequentially whenever the set of AVAILABLE_MODES changes and should match
            value of AVAILABLE_MODES_MONITOR. Note, a GCS must ignore 0 values, and should re-start the download if the
            value changes part-way through fetching modes.
            */
            [ExtensionField] byte seq;
        }

        /**
        Get the current mode.
