        /**
        Static data to configure the ADS-B transponder (send within 10 sec of a POR and every 10 sec thereafter)
        */
        class UAVIONIX_ADSB_OUT_CFG {
            public const int mavlink_message_id = 10001;
            /**
            Vehicle address (24 bit)
            */
            uint ICAO;
            /**
            Vehicle identifier (8 characters, null terminated, valid characters are A-Z, 0-9, " " only)
            */
            [D(+9)] string callsign;
            /**
            Transmitting vehicle type. See ADSB_EMITTER_TYPE enum
            */
            ADSB_EMITTER_TYPE emitterType;
            /**
            Aircraft length and width encoding (table 2-35 of DO-282B)
            */
            UAVIONIX_ADSB_OUT_CFG_AIRCRAFT_SIZE aircraftSize;
            /**
            GPS antenna lateral offset (table 2-36 of DO-282B)
            */
            UAVIONIX_ADSB_OUT_CFG_GPS_OFFSET_LAT gpsOffsetLat;
            /**
            GPS antenna longitudinal offset from nose [if non-zero, take position (in meters) divide by 2 and add one]
            (table 2-37 DO-282B)
            */
            UAVIONIX_ADSB_OUT_CFG_GPS_OFFSET_LON gpsOffsetLon;
            /**
            Aircraft stall speed in cm/s
            */
            [Units(SI_Unit.distance.cm_s)] ushort stallSpeed;
            /**
            ADS-B transponder receiver and transmit enable flags
            */
            UAVIONIX_ADSB_OUT_RF_SELECT rfSelect;
        }

        /**
        Dynamic data used to generate ADS-B out transponder data (send at 5Hz)
        */
        class UAVIONIX_ADSB_OUT_DYNAMIC {
            public const int mavlink_message_id = 10002;
            /**
            UTC time in seconds since GPS epoch (Jan 6, 1980). If unknown set to UINT32_MAX
            */
            [Units(SI_Unit.time.s)] uint utcTime;
            /**
            Latitude WGS84 (deg * 1E7). If unknown set to INT32_MAX
            */
            [Units(SI_Unit.angle.degE7)] int gpsLat;
            /**
            Longitude WGS84 (deg * 1E7). If unknown set to INT32_MAX
            */
            [Units(SI_Unit.angle.degE7)] int gpsLon;
            /**
            Altitude (WGS84). UP +ve. If unknown set to INT32_MAX
            */
            [Units(SI_Unit.distance.mm)] int gpsAlt;
            /**
            0-1: no fix, 2: 2D fix, 3: 3D fix, 4: DGPS, 5: RTK
            */
            UAVIONIX_ADSB_OUT_DYNAMIC_GPS_FIX gpsFix;
            /**
            Number of satellites visible. If unknown set to UINT8_MAX
            */
            byte numSats;
            /**
            Barometric pressure altitude (MSL) relative to a standard atmosphere of 1013.2 mBar and NOT bar corrected
            altitude (m * 1E-3). (up +ve). If unknown set to INT32_MAX
            */
            [Units(SI_Unit.pressure.mbar)] int baroAltMSL;
            /**
            Horizontal accuracy in mm (m * 1E-3). If unknown set to UINT32_MAX
            */
            [Units(SI_Unit.distance.mm)] uint accuracyHor;
            /**
            Vertical accuracy in cm. If unknown set to UINT16_MAX
            */
            [Units(SI_Unit.distance.cm)] ushort accuracyVert;
            /**
            Velocity accuracy in mm/s (m * 1E-3). If unknown set to UINT16_MAX
            */
            [Units(SI_Unit.distance.mm_s)] ushort accuracyVel;
            /**
            GPS vertical speed in cm/s. If unknown set to INT16_MAX
            */
            [Units(SI_Unit.distance.cm_s)] short velVert;
            /**
            North-South velocity over ground in cm/s North +ve. If unknown set to INT16_MAX
            */
            [Units(SI_Unit.distance.cm_s)] short velNS;
            /**
            East-West velocity over ground in cm/s East +ve. If unknown set to INT16_MAX
            */
            [Units(SI_Unit.distance.cm_s)] short VelEW;
            /**
            Emergency status
            */
            UAVIONIX_ADSB_EMERGENCY_STATUS emergencyStatus;
            /**
            ADS-B transponder dynamic input state flags
            */
            UAVIONIX_ADSB_OUT_DYNAMIC_STATE state;
            /**
            Mode A code (typically 1200 [0x04B0] for VFR)
            */
            ushort squawk;
        }

        /**
        Transceiver heartbeat with health report (updated every 10s)
        */
        class UAVIONIX_ADSB_TRANSCEIVER_HEALTH_REPORT {
            public const int mavlink_message_id = 10003;
            /**
            ADS-B transponder messages
            */
            UAVIONIX_ADSB_RF_HEALTH rfHealth;
        }

        /**
        Aircraft Registration.
        */
        class UAVIONIX_ADSB_OUT_CFG_REGISTRATION {
            public const int mavlink_message_id = 10004;
            /**
            Aircraft Registration (ASCII string A-Z, 0-9 only), e.g. "N8644B ". Trailing spaces (0x20) only. This is
            null-terminated.
            */
            [D(+9)] string registration;
        }

        /**
        Flight Identification for ADSB-Out vehicles.
        */
        class UAVIONIX_ADSB_OUT_CFG_FLIGHTID {
            public const int mavlink_message_id = 10005;
            /**
            Flight Identification: 8 ASCII characters, '0' through '9', 'A' through 'Z' or space. Spaces (0x20) used as a
            trailing pad character, or when call sign is unavailable. Reflects Control message setting. This is
            null-terminated.
            */
            [D(+9)] string flight_id;
        }

        /**
        Request messages.
        */
        class UAVIONIX_ADSB_GET {
            public const int mavlink_message_id = 10006;
            /**
            Message ID to request. Supports any message in this 10000-10099 range
            */
            uint ReqMessageId;
        }

        /**
        Control message with all data sent in UCP control message.
        */
        class UAVIONIX_ADSB_OUT_CONTROL {
            public const int mavlink_message_id = 10007;
            /**
            ADS-B transponder control state flags
            */
            UAVIONIX_ADSB_OUT_CONTROL_STATE state;
            /**
            Barometric pressure altitude (MSL) relative to a standard atmosphere of 1013.2 mBar and NOT bar corrected
            altitude (m * 1E-3). (up +ve). If unknown set to INT32_MAX
            */
            [Units(SI_Unit.pressure.mbar)] int baroAltMSL;
            /**
            Mode A code (typically 1200 [0x04B0] for VFR)
            */
            ushort squawk;
            /**
            Emergency status
            */
            UAVIONIX_ADSB_EMERGENCY_STATUS emergencyStatus;
            /**
            Flight Identification: 8 ASCII characters, '0' through '9', 'A' through 'Z' or space. Spaces (0x20) used as a
            trailing pad character, or when call sign is unavailable.
            */
            [D(+8)] string flight_id;
            /**
            X-Bit enable (military transponders only)
            */
            byte x_bit; // values: constants container UAVIONIX_ADSB_XBIT
        }

        /**
        Status message with information from UCP Heartbeat and Status messages.
        */
        class UAVIONIX_ADSB_OUT_STATUS {
            public const int mavlink_message_id = 10008;
            /**
            ADS-B transponder status state flags
            */
            UAVIONIX_ADSB_OUT_STATUS_STATE state;
            /**
            Mode A code (typically 1200 [0x04B0] for VFR)
            */
            ushort squawk;
            /**
            Integrity and Accuracy of traffic reported as a 4-bit value for each field (NACp 7:4, NIC 3:0) and encoded by
            Containment Radius (HPL) and Estimated Position Uncertainty (HFOM), respectively
            */
            UAVIONIX_ADSB_OUT_STATUS_NIC_NACP NIC_NACp;
            /**
            Board temperature in C
            */
            byte boardTemp;
            /**
            ADS-B transponder fault flags
            */
            UAVIONIX_ADSB_OUT_STATUS_FAULT fault;
            /**
            Flight Identification: 8 ASCII characters, '0' through '9', 'A' through 'Z' or space. Spaces (0x20) used as a
            trailing pad character, or when call sign is unavailable.
            */
            [D(+8)] string flight_id;
        }

