        /**
        MAVLINK component type reported in HEARTBEAT message. Flight controllers must report the type of the vehicle
        on which they are mounted (e.g. MAV_TYPE_OCTOROTOR). All other components must report a value appropriate for
        their type (e.g. a camera must use MAV_TYPE_CAMERA).
        */
        enum MAV_TYPE {
            /**
            Generic micro air vehicle
            */
            MAV_TYPE_GENERIC = 0,
            /**
            Fixed wing aircraft.
            */
            MAV_TYPE_FIXED_WING = 1,
            /**
            Quadrotor
            */
            MAV_TYPE_QUADROTOR = 2,
            /**
            Coaxial helicopter
            */
            MAV_TYPE_COAXIAL = 3,
            /**
            Normal helicopter with tail rotor.
            */
            MAV_TYPE_HELICOPTER = 4,
            /**
            Ground installation
            */
            MAV_TYPE_ANTENNA_TRACKER = 5,
            /**
            Operator control unit / ground control station
            */
            MAV_TYPE_GCS = 6,
            /**
            Airship, controlled
            */
            MAV_TYPE_AIRSHIP = 7,
            /**
            Free balloon, uncontrolled
            */
            MAV_TYPE_FREE_BALLOON = 8,
            /**
            Rocket
            */
            MAV_TYPE_ROCKET = 9,
            /**
            Ground rover
            */
            MAV_TYPE_GROUND_ROVER = 10,
            /**
            Surface vessel, boat, ship
            */
            MAV_TYPE_SURFACE_BOAT = 11,
            /**
            Submarine
            */
            MAV_TYPE_SUBMARINE = 12,
            /**
            Hexarotor
            */
            MAV_TYPE_HEXAROTOR = 13,
            /**
            Octorotor
            */
            MAV_TYPE_OCTOROTOR = 14,
            /**
            Tricopter
            */
            MAV_TYPE_TRICOPTER = 15,
            /**
            Flapping wing
            */
            MAV_TYPE_FLAPPING_WING = 16,
            /**
            Kite
            */
            MAV_TYPE_KITE = 17,
            /**
            Onboard companion controller
            */
            MAV_TYPE_ONBOARD_CONTROLLER = 18,
            /**
            Two-rotor Tailsitter VTOL that additionally uses control surfaces in vertical operation. Note, value
            previously named MAV_TYPE_VTOL_DUOROTOR.
            */
            MAV_TYPE_VTOL_TAILSITTER_DUOROTOR = 19,
            /**
            Quad-rotor Tailsitter VTOL using a V-shaped quad config in vertical operation. Note: value previously named
            MAV_TYPE_VTOL_QUADROTOR.
            */
            MAV_TYPE_VTOL_TAILSITTER_QUADROTOR = 20,
            /**
            Tiltrotor VTOL. Fuselage and wings stay (nominally) horizontal in all flight phases. It able to tilt (some)
            rotors to provide thrust in cruise flight.
            */
            MAV_TYPE_VTOL_TILTROTOR = 21,
            /**
            VTOL with separate fixed rotors for hover and cruise flight. Fuselage and wings stay (nominally) horizontal in
            all flight phases.
            */
            MAV_TYPE_VTOL_FIXEDROTOR = 22,
            /**
            Tailsitter VTOL. Fuselage and wings orientation changes depending on flight phase: vertical for hover,
            horizontal for cruise. Use more specific VTOL MAV_TYPE_VTOL_TAILSITTER_DUOROTOR or
            MAV_TYPE_VTOL_TAILSITTER_QUADROTOR if appropriate.
            */
            MAV_TYPE_VTOL_TAILSITTER = 23,
            /**
            Tiltwing VTOL. Fuselage stays horizontal in all flight phases. The whole wing, along with any attached engine,
            can tilt between vertical and horizontal mode.
            */
            MAV_TYPE_VTOL_TILTWING = 24,
            /**
            VTOL reserved 5
            */
            MAV_TYPE_VTOL_RESERVED5 = 25,
            /**
            Gimbal
            */
            MAV_TYPE_GIMBAL = 26,
            /**
            ADSB system
            */
            MAV_TYPE_ADSB = 27,
            /**
            Steerable, nonrigid airfoil
            */
            MAV_TYPE_PARAFOIL = 28,
            /**
            Dodecarotor
            */
            MAV_TYPE_DODECAROTOR = 29,
            /**
            Camera
            */
            MAV_TYPE_CAMERA = 30,
            /**
            Charging station
            */
            MAV_TYPE_CHARGING_STATION = 31,
            /**
            FLARM collision avoidance system
            */
            MAV_TYPE_FLARM = 32,
            /**
            Servo
            */
            MAV_TYPE_SERVO = 33,
            /**
            Open Drone ID. See https://mavlink.io/en/services/opendroneid.html.
            */
            MAV_TYPE_ODID = 34,
            /**
            Decarotor
            */
            MAV_TYPE_DECAROTOR = 35,
            /**
            Battery
            */
            MAV_TYPE_BATTERY = 36,
            /**
            Parachute
            */
            MAV_TYPE_PARACHUTE = 37,
            /**
            Log
            */
            MAV_TYPE_LOG = 38,
            /**
            OSD
            */
            MAV_TYPE_OSD = 39,
            /**
            IMU
            */
            MAV_TYPE_IMU = 40,
            /**
            GPS
            */
            MAV_TYPE_GPS = 41,
            /**
            Winch
            */
            MAV_TYPE_WINCH = 42,
            /**
            Generic multirotor that does not fit into a specific type or whose type is unknown
            */
            MAV_TYPE_GENERIC_MULTIROTOR = 43,
            /**
            Illuminator. An illuminator is a light source that is used for lighting up dark areas external to the system:
            e.g. a torch or searchlight (as opposed to a light source for illuminating the system itself, e.g. an
            indicator light).
            */
            MAV_TYPE_ILLUMINATOR = 44,
            /**
            Orbiter spacecraft. Includes satellites orbiting terrestrial and extra-terrestrial bodies. Follows NASA
            Spacecraft Classification.
            */
            MAV_TYPE_SPACECRAFT_ORBITER = 45,
            /**
            A generic four-legged ground vehicle (e.g., a robot dog).
            */
            MAV_TYPE_GROUND_QUADRUPED = 46,
            /**
            VTOL hybrid of helicopter and autogyro. It has a main rotor for lift and separate propellers for forward
            flight. The rotor must be powered for hover but can autorotate in cruise flight. See:
            https://en.wikipedia.org/wiki/Gyrodyne
            */
            MAV_TYPE_VTOL_GYRODYNE = 47,
            /**
            Gripper
            */
            MAV_TYPE_GRIPPER = 48,
            /**
            Radio
            */
            MAV_TYPE_RADIO = 49,
        }

        /**
        These flags encode the MAV mode, see MAV_MODE enum for useful combinations.
        */
        [Flags]
        enum MAV_MODE_FLAG {
            /**
            0b10000000 MAV safety set to armed. Motors are enabled / running / can start. Ready to fly. Additional note:
            this flag is to be ignored when sent in the command MAV_CMD_DO_SET_MODE and MAV_CMD_COMPONENT_ARM_DISARM shall
            be used instead. The flag can still be used to report the armed state.
            */
            MAV_MODE_FLAG_SAFETY_ARMED = 128,
            /**
            0b01000000 remote control input is enabled.
            */
            MAV_MODE_FLAG_MANUAL_INPUT_ENABLED = 64,
            /**
            0b00100000 hardware in the loop simulation. All motors / actuators are blocked, but internal software is full
            operational.
            */
            MAV_MODE_FLAG_HIL_ENABLED = 32,
            /**
            0b00010000 system stabilizes electronically its attitude (and optionally position). It needs however further
            control inputs to move around.
            */
            MAV_MODE_FLAG_STABILIZE_ENABLED = 16,
            /**
            0b00001000 guided mode enabled, system flies waypoints / mission items.
            */
            MAV_MODE_FLAG_GUIDED_ENABLED = 8,
            /**
            0b00000100 autonomous mode enabled, system finds its own goal positions. Guided flag can be set or not,
            depends on the actual implementation.
            */
            MAV_MODE_FLAG_AUTO_ENABLED = 4,
            /**
            0b00000010 system has a test mode enabled. This flag is intended for temporary system tests and should not be
            used for stable implementations.
            */
            MAV_MODE_FLAG_TEST_ENABLED = 2,
            /**
            0b00000001 system-specific custom mode is enabled. When using this flag to enable a custom mode all other
            flags should be ignored.
            */
            MAV_MODE_FLAG_CUSTOM_MODE_ENABLED = 1,
        }

        /**
        These values encode the bit positions of the decode position. These values can be used to read the value of a
        flag bit by combining the base_mode variable with AND with the flag position value. The result will be either
        0 or 1, depending on if the flag is set or not.
        */
        [Flags]
        enum MAV_MODE_FLAG_DECODE_POSITION {
            /**
            First bit:  10000000
            */
            MAV_MODE_FLAG_DECODE_POSITION_SAFETY = 128,
            /**
            Second bit: 01000000
            */
            MAV_MODE_FLAG_DECODE_POSITION_MANUAL = 64,
            /**
            Third bit:  00100000
            */
            MAV_MODE_FLAG_DECODE_POSITION_HIL = 32,
            /**
            Fourth bit: 00010000
            */
            MAV_MODE_FLAG_DECODE_POSITION_STABILIZE = 16,
            /**
            Fifth bit:  00001000
            */
            MAV_MODE_FLAG_DECODE_POSITION_GUIDED = 8,
            /**
            Sixth bit:   00000100
            */
            MAV_MODE_FLAG_DECODE_POSITION_AUTO = 4,
            /**
            Seventh bit: 00000010
            */
            MAV_MODE_FLAG_DECODE_POSITION_TEST = 2,
            /**
            Eighth bit: 00000001
            */
            MAV_MODE_FLAG_DECODE_POSITION_CUSTOM_MODE = 1,
        }

        enum MAV_STATE {
            /**
            Uninitialized system, state is unknown.
            */
            MAV_STATE_UNINIT = 0,
            /**
            System is booting up.
            */
            MAV_STATE_BOOT = 1,
            /**
            System is calibrating and not flight-ready.
            */
            MAV_STATE_CALIBRATING = 2,
            /**
            System is grounded and on standby. It can be launched any time.
            */
            MAV_STATE_STANDBY = 3,
            /**
            System is active and might be already airborne. Motors are engaged.
            */
            MAV_STATE_ACTIVE = 4,
            /**
            System is in a non-normal flight mode (failsafe). It can however still navigate.
            */
            MAV_STATE_CRITICAL = 5,
            /**
            System is in a non-normal flight mode (failsafe). It lost control over parts or over the whole airframe. It is
            in mayday and going down.
            */
            MAV_STATE_EMERGENCY = 6,
            /**
            System just initialized its power-down sequence, will shut down now.
            */
            MAV_STATE_POWEROFF = 7,
            /**
            System is terminating itself (failsafe or commanded).
            */
            MAV_STATE_FLIGHT_TERMINATION = 8,
        }

        /**
        Legacy component ID values for particular types of hardware/software that might make up a MAVLink system
        (autopilot, cameras, servos, avoidance systems etc.).
        Components are not required or expected to use IDs with names that correspond to their type or function, but
        may choose to do so.
        Using an ID that matches the type may slightly reduce the chances of component id clashes, as, for historical
        reasons, it is less likely to be used by some other type of component.
        System integration will still need to ensure that all components have unique IDs.
        Component IDs are used for addressing messages to a particular component within a system.
        A component can use any unique ID between 1 and 255 (MAV_COMP_ID_ALL value is the broadcast address, used to
        send to all components).
        Historically component ID were also used for identifying the type of component.
        New code must not use component IDs to infer the component type, but instead check the MAV_TYPE in the
        HEARTBEAT message!
        */
        enum MAV_COMPONENT {
            /**
            Target id (target_component) used to broadcast messages to all components of the receiving system. Components
            should attempt to process messages with this component ID and forward to components on any other interfaces.
            Note: This is not a valid *source* component id for a message.
            */
            MAV_COMP_ID_ALL = 0,
            /**
            System flight controller component ("autopilot"). Only one autopilot is expected in a particular system.
            */
            MAV_COMP_ID_AUTOPILOT1 = 1,
            /**
            Id for a component on privately managed MAVLink network. Can be used for any purpose but may not be published
            by components outside of the private network.
            */
            MAV_COMP_ID_USER1 = 25,
