        /**
        Predefined OR-combined MAV_MODE_FLAG values. These can simplify using the flags when setting modes. Note that
        manual input is enabled in all modes as a safety override.
        ⚠ DEPRECATED since 2025-02, replaced by MAV_MODE_FLAG: Using MAV_MODE to set modes is less predictable than
        using standard modes (MAV_STANDARD_MODE) or custom modes (MAV_MODE_FLAG_CUSTOM_MODE_ENABLED).
        */
        enum MAV_MODE {
            /**
            System is not ready to fly, booting, calibrating, etc. No flag is set.
            */
            MAV_MODE_PREFLIGHT = 0,
            /**
            System is allowed to be active, under assisted RC control (MAV_MODE_FLAG_SAFETY_ARMED,
            MAV_MODE_FLAG_STABILIZE_ENABLED)
            */
            MAV_MODE_STABILIZE_DISARMED = 80,
            /**
            System is allowed to be active, under assisted RC control (MAV_MODE_FLAG_SAFETY_ARMED,
            MAV_MODE_FLAG_MANUAL_INPUT_ENABLED, MAV_MODE_FLAG_STABILIZE_ENABLED)
            */
            MAV_MODE_STABILIZE_ARMED = 208,
            /**
            System is allowed to be active, under manual (RC) control, no stabilization
            (MAV_MODE_FLAG_MANUAL_INPUT_ENABLED)
            */
            MAV_MODE_MANUAL_DISARMED = 64,
            /**
            System is allowed to be active, under manual (RC) control, no stabilization (MAV_MODE_FLAG_SAFETY_ARMED,
            MAV_MODE_FLAG_MANUAL_INPUT_ENABLED)
            */
            MAV_MODE_MANUAL_ARMED = 192,
            /**
            System is allowed to be active, under autonomous control, manual setpoint (MAV_MODE_FLAG_SAFETY_ARMED,
            MAV_MODE_FLAG_STABILIZE_ENABLED, MAV_MODE_FLAG_GUIDED_ENABLED)
            */
            MAV_MODE_GUIDED_DISARMED = 88,
            /**
            System is allowed to be active, under autonomous control, manual setpoint (MAV_MODE_FLAG_SAFETY_ARMED,
            MAV_MODE_FLAG_MANUAL_INPUT_ENABLED, MAV_MODE_FLAG_STABILIZE_ENABLED, MAV_MODE_FLAG_GUIDED_ENABLED)
            */
            MAV_MODE_GUIDED_ARMED = 216,
            /**
            System is allowed to be active, under autonomous control and navigation (the trajectory is decided onboard and
            not pre-programmed by waypoints). (MAV_MODE_FLAG_SAFETY_ARMED, MAV_MODE_FLAG_STABILIZE_ENABLED,
            MAV_MODE_FLAG_GUIDED_ENABLED, MAV_MODE_FLAG_AUTO_ENABLED).
            */
            MAV_MODE_AUTO_DISARMED = 92,
            /**
            System is allowed to be active, under autonomous control and navigation (the trajectory is decided onboard and
            not pre-programmed by waypoints). (MAV_MODE_FLAG_SAFETY_ARMED, MAV_MODE_FLAG_MANUAL_INPUT_ENABLED,
            MAV_MODE_FLAG_STABILIZE_ENABLED, MAV_MODE_FLAG_GUIDED_ENABLED,MAV_MODE_FLAG_AUTO_ENABLED).
            */
            MAV_MODE_AUTO_ARMED = 220,
            /**
            UNDEFINED mode. This solely depends on the autopilot - use with caution, intended for developers only.
            (MAV_MODE_FLAG_MANUAL_INPUT_ENABLED, MAV_MODE_FLAG_TEST_ENABLED).
            */
            MAV_MODE_TEST_DISARMED = 66,
            /**
            UNDEFINED mode. This solely depends on the autopilot - use with caution, intended for developers only
            (MAV_MODE_FLAG_SAFETY_ARMED, MAV_MODE_FLAG_MANUAL_INPUT_ENABLED, MAV_MODE_FLAG_TEST_ENABLED)
            */
            MAV_MODE_TEST_ARMED = 194,
        }

