            MAV_CMD_NAV_PAYLOAD_PLACE = 94,
            /**
            NOP - This command is only used to mark the upper limit of the NAV/ACTION commands in the enumeration
            */
            MAV_CMD_NAV_LAST = 95,
            /**
            Delay mission state machine.
            */
            MAV_CMD_CONDITION_DELAY = 112,
            /**
            Ascend/descend to target altitude at specified rate. Delay mission state machine until desired altitude
            reached.
            */
            MAV_CMD_CONDITION_CHANGE_ALT = 113,
            /**
            Delay mission state machine until within desired distance of next NAV point.
            */
            MAV_CMD_CONDITION_DISTANCE = 114,
            /**
            Reach a certain target angle.
            */
            MAV_CMD_CONDITION_YAW = 115,
            /**
            NOP - This command is only used to mark the upper limit of the CONDITION commands in the enumeration
            */
            MAV_CMD_CONDITION_LAST = 159,
            /**
            Set system mode.
            */
            MAV_CMD_DO_SET_MODE = 176,
            /**
            Jump to the desired command in the mission list.  Repeat this action only the specified number of times
            */
            MAV_CMD_DO_JUMP = 177,
            /**
            Change speed and/or throttle set points. The value persists until it is overridden or there is a mode change
            */
            MAV_CMD_DO_CHANGE_SPEED = 178,
            /**
            Sets the home position to either to the current position or a specified position.
            The home position is the default position that the system will return to and land on.
            The position is set automatically by the system during the takeoff (and may also be set using this command).
