        /**
            Non-transmittable constants container: per-command parameter conventions of MAV_CMD.
            Each nested struct is named after the command; param_N holds the MAVLink &lt;param&gt; metadata.
        */
        public struct MAV_CMD_PARAMS {
            public struct MAV_CMD_NAV_WAYPOINT {
                public const long value = 16;
                public const bool hasLocation = true;
                public const bool isDestination = true;
                public const bool mission = true;
                public struct param_1 {
                    public const int index = 1;
                    public const string label = "Hold";
                    public const string units = SI_Unit.time.s;
                    public const long minValue = 0;
                    public const string description = @"Hold time. (ignored by fixed wing, time to stay at waypoint for rotary wing)";
                }
                public struct param_2 {
                    public const int index = 2;
                    public const string label = "Accept Radius";
                    public const string units = SI_Unit.distance.m;
                    public const long minValue = 0;
                    public const string description = @"Acceptance radius (if the sphere with this radius is hit, the waypoint counts as reached)";
                }
                public struct param_3 {
                    public const int index = 3;
                    public const string label = "Pass Radius";
                    public const string units = SI_Unit.distance.m;
                    public const string description = @"0 to pass through the WP, if > 0 radius to pass by WP. Positive value for clockwise orbit, negative value for counter-clockwise orbit. Allows trajectory control.";
                }
                public struct param_4 {
                    public const int index = 4;
                    public const string label = "Yaw";
                    public const string units = SI_Unit.angle.deg;
                    public const string description = @"Desired yaw angle at waypoint (rotary wing). NaN to use the current system yaw heading mode (e.g. yaw towards next waypoint, yaw to home, etc.).";
                }
                public struct param_5 {
                    public const int index = 5;
                    public const string label = "Latitude";
                    public const string description = @"Latitude";
                }
                public struct param_6 {
                    public const int index = 6;
                    public const string label = "Longitude";
                    public const string description = @"Longitude";
                }
                public struct param_7 {
                    public const int index = 7;
                    public const string label = "Altitude";
                    public const string units = SI_Unit.distance.m;
                    public const string description = @"Altitude";
                }
            }
            public struct MAV_CMD_NAV_LOITER_UNLIM {
                public const long value = 17;
                public const bool command = true;
                public const bool hasLocation = true;
                public const bool isDestination = true;
                public const bool mission = true;
                public struct param_1 {
                    public const int index = 1;
                    public const string description = @"Empty";
                }
                public struct param_2 {
                    public const int index = 2;
                    public const string description = @"Empty";
                }
                public struct param_3 {
                    public const int index = 3;
                    public const string label = "Radius";
                    public const string units = SI_Unit.distance.m;
                    public const string description = @"Loiter radius around waypoint for forward-only moving vehicles (not multicopters). If positive loiter clockwise, else counter-clockwise";
                }
                public struct param_4 {
